import{_ as n,o,c as t,a0 as i}from"./chunks/framework.Bkgi-hoF.js";const u=JSON.parse('{"title":"Environments","description":"","frontmatter":{},"headers":[],"relativePath":"features/environments.md","filePath":"features/environments.md"}'),a={name:"features/environments.md"};function r(s,e,l,c,d,m){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to &quot;Environments&quot;">​</a></h1><p>Environments separate your configurations by deployment stage. A single project can have multiple environments like development, staging, and production — each with its own configs, API keys, and domain restrictions.</p><h2 id="default-setup" tabindex="-1">Default Setup <a class="header-anchor" href="#default-setup" aria-label="Permalink to &quot;Default Setup&quot;">​</a></h2><p>When you create a project, you typically create environments for:</p><ul><li><strong>Development</strong> — for local testing</li><li><strong>Staging</strong> — for QA and pre-release testing</li><li><strong>Production</strong> — for live users</li></ul><h2 id="environment-specific-configs" tabindex="-1">Environment-Specific Configs <a class="header-anchor" href="#environment-specific-configs" aria-label="Permalink to &quot;Environment-Specific Configs&quot;">​</a></h2><p>Each environment has its own set of config values. A flag can be:</p><ul><li><code>true</code> in development (always enabled for devs)</li><li><code>true</code> in staging (testing before launch)</li><li><code>false</code> in production (not yet released)</li></ul><h2 id="api-keys-per-environment" tabindex="-1">API Keys Per Environment <a class="header-anchor" href="#api-keys-per-environment" aria-label="Permalink to &quot;API Keys Per Environment&quot;">​</a></h2><p>Each environment has its own API keys:</p><ul><li>Generate a <code>cid_</code> key for your production frontend</li><li>Generate a separate <code>cid_</code> key for your staging frontend</li><li>Keys from one environment cannot access another environment&#39;s configs</li></ul><h2 id="domain-validation" tabindex="-1">Domain Validation <a class="header-anchor" href="#domain-validation" aria-label="Permalink to &quot;Domain Validation&quot;">​</a></h2><p>For additional security, you can set <strong>allowed domains</strong> per environment:</p><ul><li>Production: <code>myapp.com</code>, <code>www.myapp.com</code></li><li>Staging: <code>staging.myapp.com</code></li><li>Development: <code>localhost</code></li></ul><p>Requests from non-allowed domains are rejected with a 403 error.</p><h2 id="environment-colors" tabindex="-1">Environment Colors <a class="header-anchor" href="#environment-colors" aria-label="Permalink to &quot;Environment Colors&quot;">​</a></h2><p>Assign colors to environments for quick visual identification in the portal. Production environments can be marked with an <code>isProduction</code> flag to trigger confirmation prompts before changes.</p><h2 id="switching-environments" tabindex="-1">Switching Environments <a class="header-anchor" href="#switching-environments" aria-label="Permalink to &quot;Switching Environments&quot;">​</a></h2><p>Use the environment switcher in the portal&#39;s top bar to switch context. All configs, API keys, and targeting rules shown are scoped to the selected environment.</p>',19)])])}const h=n(a,[["render",r]]);export{u as __pageData,h as default};
